window.AUTH=window.AUTH||{};window.AUTH["22-888"]={"d":"22-888","id":"2023/22-888","n":"Rudisill v. McDonough","briefs":[{"k":"petitioner","label":"Brief of petitioner James R. Rudisill","date":"2023-08-10","url":"https://www.supremecourt.gov/DocketPDF/22/22-888/275044/20230810125518713_Rudisill%20v.%20McDonough%20-%20Brief%20For%20Petitioner.pdf","side":"pet","n":60},{"k":"respondent","label":"Brief of respondent Denis McDonough, Secretary of Veterans Affairs","date":"2023-09-11","url":"https://www.supremecourt.gov/DocketPDF/22/22-888/279347/20230911181052651_22-888bsUnitedStates.pdf","side":"res","n":69},{"k":"reply","label":"Reply of petitioner James R. Rudisill","date":"2023-10-11","url":"https://www.supremecourt.gov/DocketPDF/22/22-888/284679/20231011124351848_22-888_Reply%20brief.pdf","side":"pet","n":26}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us2r16_2dp3.pdf","tr":true,"items":[{"t":"case","label":"Biden v. Texas","cite":"142 S. Ct. 2528","y":2022,"id":"2021/21-954","sc":1,"sum":"The Government’s rescission of Migrant Protection Protocols did not violate section 1225 of the Immigration and Nationality Act, and the then-Secretary of Homeland Security’s October 29 Memoranda constituted valid final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"44"}},{"t":"case","label":"Boone v. Lightner","cite":"319 U.S. 561","y":1943,"id":"scdb/1942-138","sc":1,"op":1,"sum":"Section 201 of the Soldiers' and Sailors' Civil Relief Act of 1940, providing for stays in court proceedings involving persons in military service, addresses to the discretion of the court the question whether \"the ability of... the defendant to conduct his defense is not materially affected by reason of his military service.\" In the circumstances of this case, denial of a stay at the instance of a defendant in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 58, 59"}},{"t":"case","label":"BP Am. Prod. Co. v. Burton","cite":"549 U.S. 84","y":2006,"id":"2006/05-669","sc":1,"sum":"The Court ruled 7-0 that \"the 6-year statute of limitations in 2415(a) applies only to court actions and not to the administrative proceedings involved in this case.\" The opinion by Justice Samuel Alito relied on the plain meaning of the language in Section 2415(a). The statute used the terms \"action\" and \"complaint\" when referring to the statute of limitations.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Brown v. Bd. of Educ.","cite":"347 U.S. 483","y":1954,"id":"1940-1955/347us483","sc":1,"sum":"The Court decided that the \"separate but equal\" standards of racial segregation were unconstitutional, paving the way for the Civil Rights Movement and national desegregation.","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Carr v. Wilkie","cite":"961 F.3d 1168","y":2020,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/961/1168/","by":{"0":"12"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"0":"37, 54","2":"6"}},{"t":"case","label":"Fishgold v. Sullivan Drydock & Repair Corp.","cite":"328 U.S. 275","y":1946,"id":"scdb/1945-102","sc":1,"sum":"After serving in the Army and receiving an honorable discharge, petitioner was reinstated in his former position pursuant to § 8 (a) of the Selective Training and Service Act of 1940. Subsequently, when there was not enough work to keep all employees busy, he was laid off temporarily on nine days while non-veterans with higher shop seniorities were permitted to work; but he was given work when enough became …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"58"}},{"t":"case","label":"Fla. Dep’t of Rev. v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"sum":"The Court held 7-2 that the plain meaning of the statute indicates that it only applies to confirmed asset sales, not \"pre-confirmation\" sales.","sumSrc":"Oyez","by":{"0":"37, 48"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"op":2,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"59","1":"31","2":"25, 26"}},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"op":2,"sum":"Section 2024(d) does not limit the length of military service after which a member of the Armed Forces retains a right to civilian reemployment. Subsection (d)'s text-which specifies that any covered employee \"shall... be granted a leave... for the period required to perform active duty [and] [u]pon... release from... such duty... shall be permitted to return to [his or her] position\"-is utterly silent about any …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting Grp., Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"op":1,"sum":"The Court held that the safe harbor provision of 11 U.S.C. § 546(e), which prohibits a trustee from avoiding a transfer made by or to a financial institution, does not include transfers where the benefit and detriment of the transfer impact companies that are not financial institutions.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Opati v. Republic of Sudan","cite":"140 S. Ct. 1601","y":2020,"id":"2019/17-1268","sc":1,"op":1,"sum":"The Court held that the Foreign Sovereign Immunities Act (FSIA) applies retroactively, thereby permitting recovery of punitive damages against foreign states for terrorist activities occurring prior to the passage of the current version of the statute.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Rowland v. Cal. Men’s Colony","cite":"506 U.S. 194","y":1993,"id":"1992/91-1188","sc":1,"sum":"In a suit filed in the District Court against petitioner state correctional officers, respondent, a representative association of inmates in a California prison, sought leave to proceed in forma pauperis under 28 U. S. C. § 1915(a), which permits litigation without prepayment of fees, costs, or security \"by a person who makes affidavit that he is unable to pay.\" The court denied the motion for an inadequate showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 48, 53"}},{"t":"case","label":"Rudisill v. Chesapeake & Ohio Ry. Co.","cite":"167 F.2d 175","y":1948,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/167/175/","by":{"0":"59"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"50"}},{"t":"usc","label":"10 U.S.C. § 1143","url":"https://www.law.cornell.edu/uscode/text/10/1143","by":{"0":"7"}},{"t":"usc","label":"10 U.S.C. § 2141","url":"https://www.law.cornell.edu/uscode/text/10/2141","by":{"0":"7"}},{"t":"usc","label":"10 U.S.C. § 16131","url":"https://www.law.cornell.edu/uscode/text/10/16131","by":{"0":"7, 11"}},{"t":"usc","label":"10 U.S.C. § 16163","url":"https://www.law.cornell.edu/uscode/text/10/16163","by":{"0":"14"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"5"}},{"t":"usc","label":"38 U.S.C. § 3001","url":"https://www.law.cornell.edu/uscode/text/38/3001","stext":{"head":"§3001. Purposes","paras":[[0,"The purposes of this chapter are—"],[1,"(1) to provide a new educational assistance program to assist in the readjustment of members of the Armed Forces to civilian life after their separation from military service;"],[1,"(2) to extend the benefits of a higher education to qualifying men and women who might not otherwise be able to afford such an education;"],[1,"(3) to provide for vocational readjustment and to restore lost educational opportunities to those service men and women who served on active duty after June 30, 1985;"],[1,"(4) to promote and assist the All-Volunteer Force program and the Total Force Concept of the Armed Forces by establishing a new program of educational assistance based upon service on active duty or a combination of service on active duty and in the Selected Reserve (including the National Guard) to aid in the recruitment and retention of highly qualified personnel for both the active and reserve components of the Armed Forces;"],[1,"(5) to give special emphasis to providing educational assistance benefits to aid in the retention of personnel in the Armed Forces; and"],[1,"(6) to enhance our Nation's competitiveness through the development of a more highly educated and productive work force."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3001?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3001. Purposes","tname":"Veterans' Benefits","by":{"0":"13","1":"2"}},{"t":"usc","label":"38 U.S.C. § 3011","url":"https://www.law.cornell.edu/uscode/text/38/3011","subs":["(a)","(a)(1)(A)","(a)(1)(A)(i)","(b)"],"stext":{"head":"§3011. Basic educational assistance entitlement for service on active duty","paras":[[0,"(a) Except as provided in subsection (c) of this section, each individual—"],[1,"(1) who—"],[2,"(A) during the period beginning July 1, 1985, and ending September 30, 2030, first becomes a member of the Armed Forces or first enters on active duty as a member of the Armed Forces and—"],[3,"(i) who (I) in the case of an individual whose obligated period of active duty is three years or more, serves at least three years of continuous active duty in the Armed Forces, or (II) in the case of an individual whose obligated period of active duty is less than three years, serves at least two years of continuous active duty in the Armed Forces; or"],[3,"(ii) who serves in the Armed Forces and is discharged or released from active duty (I) for a service-connected disability, by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10), for a medical condition which preexisted such service on active duty and which the Secretary determines is not service connected, for hardship, or for a physical or mental condition that was not characterized as a disability and did not result from the individual's own willful misconduct but did interfere with the individual's performance of duty, as determined by the Secretary of each military department in accordance with regulations prescribed by the Secretary of Defense or by the Secretary of Homeland Security with respect to the Coast Guard when it is not operating as a service in the Navy; (II) for the convenience of the Government, if, in the case of an individual with an obligated period of service of two years, the individual completes not less than 20 months of continuous active duty under that period of obligated service, or, in the case of an individual with an obligated period of service of at least three years, the individual completes not less than 30 months of continuous active duty under that period of obligated service; or (III) involuntarily for the convenience of the Government as a result of a reduction in force, as determined by the Secretary of the military department concerned in accordance with regulations prescribed by the Secretary of Defense or by the Secretary of Homeland Security with respect to the Coast Guard when it is not operating as a service in the Navy;"],[2,"(B) as of December 31, 1989, is eligible for educational assistance benefits under chapter 34 of this title and was on active duty at any time during the period beginning on October 19, 1984, and ending on July 1, 1985, continued on active duty without a break in service and—"],[3,"(i) after June 30, 1985, serves at least three years of continuous active duty in the Armed Forces; or"],[3,"(ii) after June 30, 1985, is discharged or released from active duty (I) for a service-connected disability, by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10), for a medical condition which preexisted such service on active duty and which the Secretary determines is not service connected, for hardship, or for a physical or mental condition that was not characterized as a disability, as described in subparagraph (A)(ii)(I) of this paragraph; (II) for the convenience of the Government, if the individual completed not less than 30 months of continuous active duty after that date; or (III) involuntarily for the convenience of the Government as a result of a reduction in force, as determined by the Secretary of the military department concerned in accordance with regulations prescribed by the Secretary of Defense or by the Secretary of Homeland Security with respect to the Coast Guard when it is not operating as a service in the Navy; or"],[2,"(C) as of December 31, 1989, was eligible for educational assistance benefits under chapter 34 of this title and—"],[3,"(i) was not on active duty on October 19, 1984;"],[3,"(ii) reenlists or reenters on a period of active duty after October 19, 1984; and"],[3,"(iii) on or after July 1, 1985, either—"],[4,"(I) serves at least three years of continuous active duty in the Armed Forces; or"],[4,"(II) is discharged or released from active duty (aa) for a service-connected disability, by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10), for a medical condition which preexisted such service on active duty and which the Secretary determines is not service connected, for hardship, or for a physical or mental condition that was not characterized as a disability, as described in subparagraph (A)(ii)(I) of this paragraph, (bb) for the convenience of the Government, if the individual completed not less than 30 months of continuous active duty after that date, or (cc) involuntarily for the convenience of the Government as a result of a reduction in force, as determined by the Secretary of the military department concerned in accordance with regulations prescribed by the Secretary of Defense or by the Secretary of Homeland Security with respect to the Coast Guard when it is not operating as a service in the Navy;"],[1,"(2) who completes the requirements of a secondary school diploma (or equivalency certificate), or successfully completes (or otherwise receives academic credit for) the equivalent of 12 semester hours in a program of education leading to a standard college degree, before applying for benefits under this section; and"],[1,"(3) who, after completion of the service described in clause (1) of this subsection—"],[2,"(A) continues on active duty;"],[2,"(B) is discharged from active duty with an honorable discharge;"],[2,"(C) is released after service on active duty characterized by the Secretary concerned as honorable service and is placed on the retired list, is transferred to the Fleet Reserve or Fleet Marine Corps Reserve, or is placed on the temporary disability retired list; or"],[2,"(D) is released from active duty for further service in a reserve component of the Armed Forces or for further service in the Space Force in a space force active status not on sustained duty under section 20105 of title 10 after service on active duty characterized by the Secretary concerned as honorable service;"],[0,"is entitled to basic educational assistance under this chapter."],[0,"(b)(1) Except as provided in paragraph (2), the basic pay of any individual described in subsection (a)(1)(A) of this section who does not make an election under subsection (c)(1) of this section shall be reduced by $100 for each of the first 12 months that begin after the date that is 270 days after the date on which the individual initially enters initial training."],[0,"(2) In the case of an individual covered by paragraph (1) who is a member of the Selected Reserve, the Secretary of Defense shall collect from the individual an amount equal to $1,200 not later than one year after completion by the individual of the two years of service on active duty providing the basis for such entitlement. The Secretary of Defense may collect such amount through reductions in basic pay in accordance with paragraph (1) or through such other method as the Secretary of Defense considers appropriate."],[0,"(3) Any amount by which the basic pay of an individual is reduced under this subsection shall revert to the Treasury and shall not, for purposes of any Federal law, be considered to have been received by or to be within the control of such individual."],[0,"(c)(1) An individual described in subsection (a)(1)(A) of this section may make an election not to receive educational assistance under this chapter. Any such election shall be made during the 90-day period beginning on the day that is 180 days after the date on which the individual initially enters initial training. Any individual who makes such an election is not entitled to educational assistance under this chapter."],[0,"(2) An individual who after December 31, 1976, receives a commission as an officer in the Armed Forces upon graduation from the United States Military Academy, the United States Naval Academy, the United States Air Force Academy, or the Coast Guard Academy is not eligible for educational assistance under this section."],[0,"(3) An individual who after December 31, 1976, receives a commission as an officer in the Armed Forces upon completion of a program of educational assistance under section 2107 of title 10 is not eligible for educational assistance under this section if the individual enters on active duty—"],[1,"(A) before October 1, 1996; or"],[1,"(B) after September 30, 1996, and while participating in such program received more than $3,400 for each year of such participation."],[0,"(d)(1) For purposes of this chapter, any period of service described in paragraphs (2) and (3) of this subsection shall not be considered a part of an obligated period of active duty on which an individual's entitlement to assistance under this section is based."],[0,"(2) The period of service referred to in paragraph (1) is any period terminated because of a defective enlistment and induction based on—"],[1,"(A) the individual's being a minor for purposes of service in the Armed Forces;"],[1,"(B) an erroneous enlistment or induction; or"],[1,"(C) a defective enlistment agreement."],[0,"(3) The period of service referred to in paragraph (1) is also any period of service on active duty which an individual in the Selected Reserve was ordered to perform under section 12301, 12302, 12304, 12306, or 12307 of title 10 for a period of less than 2 years."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3011?type=usc&year=mostrecent&link-type=html"},"head":"§3011. Basic educational assistance entitlement for service on active duty","tname":"Veterans' Benefits","by":{"0":"3, 13, 14, 17, 18, 25, 38, 39, 41, 56","1":"2, 3, 2, 19, 3","2":"3"}},{"t":"usc","label":"38 U.S.C. § 3013","url":"https://www.law.cornell.edu/uscode/text/38/3013","subs":["(a)(1)"],"stext":{"head":"§3013. Duration of basic educational assistance","paras":[[0,"(a)(1) Subject to section 3695 of this title and except as provided in paragraph (2) of this subsection, each individual entitled to basic educational assistance under section 3011 of this title is entitled to 36 months of educational assistance benefits under this chapter (or the equivalent thereof in part-time educational assistance)."],[0,"(2) Subject to section 3695 of this title and subsection (d) of this section, in the case of an individual described in section 3011(a)(1)(A)(ii)(I) or (III) of this title who is not also described in section 3011(a)(1)(A)(i) of this title or an individual described in section 3011(a)(1)(B)(ii)(I) or (III) of this title who is not also described in section 3011(a)(1)(B)(i) of this title, the individual is entitled to one month of educational assistance benefits under this chapter for each month of continuous active duty served by such individual after June 30, 1985, as part of the obligated period of active duty on which such entitlement is based in the case of an individual described in section 3011(a)(1)(A)(ii)(I) or (III) of this title, or in the case of an individual described in section 3011(a)(1)(B)(ii)(I) or (III) of this title, after June 30, 1985."],[0,"(b) Subject to section 3695 of this title and subsection (d) of this section, each individual entitled to basic educational assistance under section 3012 of this title is entitled to (1) one month of educational assistance benefits under this chapter for each month of continuous active duty served by such individual after June 30, 1985, as part of the obligated period of active duty on which such entitlement is based in the case of an individual described in section 3012(a)(1)(A) of this title, or in the case of an individual described in section 3012(a)(1)(B) of this title, after June 30, 1985, and (2) one month of educational assistance benefits under this chapter for each four months served by such individual in the Selected Reserve after the applicable date specified in clause (1) of this subsection (other than any month in which the individual served on active duty)."],[0,"(c)(1) Subject to section 3695 of this title and except as provided in paragraphs (2) and (3) of this subsection, each individual entitled to basic educational assistance under section 3018 of this title is entitled to 36 months of educational assistance under this chapter (or the equivalent thereof in part-time educational assistance)."],[0,"(2) Subject to section 3695 of this title, an individual described in clause (B) or (C) of section 3018(b)(3) of this title whose discharge or release from active duty prevents the reduction of the basic pay of such individual by $1,200 is entitled to the number of months of assistance under this chapter that is equal to the lesser of—"],[1,"(A) 36 multiplied by a fraction the numerator of which is the amount by which the basic pay of the individual has been reduced under section 3018(c) and the denominator of which is $1,200; or"],[1,"(B) the number of months the individual has served on continuous active duty after June 30, 1985."],[0,"(3) Subject to section 3695 of this title and subsection (d) of this section, an individual described in clause (B) or (C)(ii) of section 3018(b)(3) of this title (other than an individual described in paragraph (2) of this subsection) is entitled to the number of months of educational assistance under this chapter that is equal to the number of months the individual has served on continuous active duty after June 30, 1985."],[0,"(d) Subject to section 3695 of this title, each individual entitled to educational benefits under section 3018A, 3018B, or 3018C of this title is entitled to the lesser of—"],[1,"(1) 36 months of educational assistance under this chapter (or the equivalent thereof in part-time educational assistance); or"],[1,"(2) the number of months of such educational assistance (or such equivalent thereof) that is equal to the number of months served by such individual on active duty."],[0,"(e) No individual may receive basic educational assistance benefits under this chapter for a period in excess of 36 months (or the equivalent thereof in part-time educational assistance)."],[0,"(f)(1) Notwithstanding any other provision of this chapter or chapter 36 of this title, any payment of an educational assistance allowance described in paragraph (2) shall not—"],[1,"(A) be charged against any entitlement of any individual under this chapter; or"],[1,"(B) be counted toward the aggregate period for which section 3695 of this title limits an individual's receipt of assistance."],[0,"(2) Subject to paragraph (3), the payment of the educational assistance allowance referred to in paragraph (1) is the payment of such an allowance to an individual for pursuit of a course or courses under this chapter if the Secretary finds that the individual—"],[1,"(A) in the case of a person not serving on active duty, had to discontinue such course pursuit as a result of being ordered to serve on active duty under section 688, 12301(a), 12301(d), 12301(g), 12302, or 12304 of title 10; or"],[1,"(B) in the case of a person serving on active duty, had to discontinue such course pursuit as a result of being ordered to a new duty location or assignment or to perform an increased amount of work; and"],[1,"(C) failed to receive credit or lost training time toward completion of the individual's approved education, professional, or vocational objective as a result of having to discontinue, as described in subparagraph (A) or (B), his or her course pursuit."],[0,"(3) The period for which, by reason of this subsection, an educational assistance allowance is not charged against entitlement or counted toward the applicable aggregate period under section 3695 of this title shall not exceed the portion of the period of enrollment in the course or courses for which the individual failed to receive credit or with respect to which the individual lost training time, as determined under paragraph (2)(C) of this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3013?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3013. Duration of basic educational assistance","tname":"Veterans' Benefits","by":{"0":"11, 13, 17, 49","1":"2, 28","2":"4"}},{"t":"usc","label":"38 U.S.C. § 3014","url":"https://www.law.cornell.edu/uscode/text/38/3014","subs":["(a)"],"stext":{"head":"§3014. Payment of basic educational assistance","paras":[[0,"(a) The Secretary shall pay to each individual entitled to basic educational assistance who is pursuing an approved program of education a basic educational assistance allowance to help meet, in part, the expenses of such individual's subsistence, tuition, fees, supplies, books, equipment, and other educational costs."],[0,"(b)(1) In the case of an individual entitled to basic educational assistance who is pursuing education or training described in subsection (a) or (c) of section 2007 of title 10, the Secretary shall, at the election of the individual, pay the individual a basic educational assistance allowance to meet all or a portion of the charges of the educational institution for the education or training that are not paid by the Secretary of the military department concerned under such subsection."],[0,"(2)(A) The amount of the basic educational assistance allowance payable to an individual under this subsection for a month shall be the amount of the basic educational assistance allowance to which the individual would be entitled for the month under section 3015 of this title."],[0,"(B) The maximum number of months for which an individual may be paid a basic educational assistance allowance under paragraph (1) is 36."],[0,"(C) The number of months of entitlement charged under this chapter in the case of an individual who has been paid a basic educational assistance allowance under this subsection shall be equal to the number (including any fraction) determined by dividing the total amount of such educational assistance allowance paid the individual by the full-time monthly institutional rate of educational assistance which such individual would otherwise be paid under subsection (a)(1), (b)(1), (c)(1), (d)(1), or (e)(1) of section 3015 of this title, as the case may be."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3014?type=usc&year=mostrecent&link-type=html"},"head":"§3014. Payment of basic educational assistance","tname":"Veterans' Benefits","by":{"0":"13, 49","1":"3"}},{"t":"usc","label":"38 U.S.C. § 3015","url":"https://www.law.cornell.edu/uscode/text/38/3015","stext":{"head":"§3015. Amount of basic educational assistance","paras":[[0,"(a) The amount of payment of educational assistance under this chapter is subject to section 3032 of this title. Except as otherwise provided in this section, in the case of an individual entitled to an educational assistance allowance under this chapter whose obligated period of active duty on which such entitlement is based is three years, a basic educational assistance allowance under this subchapter shall be paid—"],[1,"(1) for an approved program of education pursued on a full-time basis, at the monthly rate of—"],[2,"(A) for months occurring during the period beginning on August 1, 2008, and ending on the last day of fiscal year 2009, $1,321; and"],[2,"(B) for months occurring during a subsequent fiscal year, the amount for months occurring during the previous fiscal year increased under subsection (h); or"],[1,"(2) at an appropriately reduced rate, as determined under regulations which the Secretary shall prescribe, for an approved program of education pursued on less than a full-time basis."],[0,"(b) In the case of an individual entitled to an educational assistance allowance under section 3011 or 3018 of this title whose obligated period of active duty on which such entitlement is based is two years, a basic educational assistance allowance under this chapter shall (except as provided in the succeeding subsections of this section) be paid—"],[1,"(1) for an approved program of education pursued on a full-time basis, at the monthly rate of—"],[2,"(A) for months occurring during the period beginning on August 1, 2008, and ending on the last day of fiscal year 2009, $1,073; and"],[2,"(B) for months occurring during a subsequent fiscal year, the amount for months occurring during the previous fiscal year increased under subsection (h); or"],[1,"(2) at an appropriately reduced rate, as determined under regulations which the Secretary shall prescribe, for an approved program of education pursued on less than a full-time basis."],[0,"(c)(1) The amount of basic educational allowance payable under this chapter to an individual referred to in paragraph (2) of this subsection is the amount determined under subsection (a) of this section."],[0,"(2) Paragraph (1) of this subsection applies to an individual entitled to an educational assistance allowance under section 3011 of this title—"],[1,"(A) whose obligated period of active duty on which such entitlement is based is less than three years;"],[1,"(B) who, beginning on the date of the commencement of such obligated period of active duty, serves a continuous period of active duty of not less than three years; and"],[1,"(C) who, after the completion of that continuous period of active duty, meets one of the conditions set forth in subsection (a)(3) of such section 3011."],[0,"(d)(1) In the case of an individual who has a skill or specialty designated by the Secretary concerned as a skill or specialty in which there is a critical shortage of personnel or for which it is difficult to recruit, the Secretary concerned, pursuant to regulations to be prescribed by the Secretary of Defense, may, at the time the individual first becomes a member of the Armed Forces, increase the rate of the basic educational assistance allowance applicable to such individual to such rate in excess of the rate prescribed under subsections (a), (b), and (c) of this section as the Secretary of Defense considers appropriate, but the amount of any such increase may not exceed $950 per month."],[0,"(2) In the case of an individual who after October 7, 1997, receives an enlistment bonus under section 308a or 308f 1 of title 37, receipt of that bonus does not affect the eligibility of that individual for an increase under paragraph (1) in the rate of the basic educational assistance allowance applicable to that individual, and the Secretary concerned may provide such an increase for that individual (and enter into an agreement with that individual that the United States agrees to make payments pursuant to such an increase) without regard to any provision of law (enacted before, on, or after the date of the enactment of this paragraph) that limits the authority to make such payments."],[0,"(e)(1)(A) Except as provided in subparagraph (B) of this paragraph and subject to paragraph (2) of this subsection, in the case of an individual who on December 31, 1989, was entitled to educational assistance under chapter 34 of this title, the rate of the basic educational assistance allowance applicable to such individual under this chapter shall be increased by the amount equal to one-half of the educational assistance allowance that would be applicable to such individual under such chapter 34 (as of the time the assistance under this chapter is provided and based on the rates in effect on December 31, 1989) if such chapter were in effect."],[0,"(B) Notwithstanding subparagraph (A) of this paragraph, in the case of an individual described in that subparagraph who is pursuing a cooperative program on or after October 9, 1996, the rate of the basic educational assistance allowance applicable to such individual under this chapter shall be increased by the amount equal to one-half of the educational assistance allowance that would be applicable to such individual for pursuit of full-time institutional training under chapter 34 (as of the time the assistance under this chapter is provided and based on the rates in effect on December 31, 1989) if such chapter were in effect."],[0,"(2) The number of months for which the rate of the basic educational assistance allowance applicable to an individual is increased under paragraph (1) of this subsection may not exceed the number of months of entitlement to educational assistance under chapter 34 of this title that the individual had remaining on December 31, 1989."],[0,"(f) In the case of an individual for whom the Secretary of Defense made contributions under section 3222(c) of this title and who is entitled to educational assistance under section 3018A, 3018B, or 3018C of this chapter, the Secretary shall increase the rate of the basic educational assistance allowance applicable to such individual in excess of the rate provided under subsection (a) of this section in a manner consistent with, as determined by the Secretary of Defense, the agreement entered into with such individual pursuant to the rules and regulations issued by the Secretary of Defense under section 3222(c) of this title."],[0,"(g) In the case of an individual who has made contributions authorized by section 3011(e) or 3012(f) of this title, effective as of the first day of the enrollment period following receipt of such contributions from such individual by the Secretary concerned, the monthly amount of basic educational assistance allowance applicable to such individual under subsection (a), (b), or (c) shall be the monthly rate otherwise provided for under the applicable subsection increased by—"],[1,"(1) an amount equal to $5 for each $20 contributed by such individual under section 3011(e) or 3012(f) of this title, as the case may be, for an approved program of education pursued on a full-time basis; or"],[1,"(2) an appropriately reduced amount based on the amount so contributed, as determined under regulations which the Secretary shall prescribe, for an approved program of education pursued on less than a full-time basis."],[0,"(h)(1) With respect to any fiscal year, the Secretary shall provide a percentage increase in the rates payable under subsections (a)(1) and (b)(1) equal to the percentage by which—"],[1,"(A) the average cost of undergraduate tuition in the United States, as determined by the National Center for Education Statistics, for the last academic year preceding the beginning of the fiscal year for which the increase is made, exceeds"],[1,"(B) the average cost of undergraduate tuition in the United States, as so determined, for the academic year preceding the academic year described in subparagraph (A)."],[0,"(2) Any increase under paragraph (1) in a rate with respect to a fiscal year after fiscal year 2004 and before fiscal year 2014 shall be rounded down to the next lower whole dollar amount. Any such increase with respect to a fiscal year after fiscal year 2013 shall be rounded to the nearest whole dollar amount."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3015?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3015. Amount of basic educational assistance","tname":"Veterans' Benefits","by":{"0":"23","1":"3"}},{"t":"usc","label":"38 U.S.C. § 3018A","url":"https://www.law.cornell.edu/uscode/text/38/3018A","by":{"0":"18"}},{"t":"usc","label":"38 U.S.C. § 3018B","url":"https://www.law.cornell.edu/uscode/text/38/3018B","by":{"0":"18"}},{"t":"usc","label":"38 U.S.C. § 3033","url":"https://www.law.cornell.edu/uscode/text/38/3033","stext":{"head":"§3033. Bar to duplication of educational assistance benefits","paras":[[0,"(a)(1) An individual entitled to educational assistance under a program established by this chapter who is also eligible for educational assistance under a program under chapter 31, 32, 33, or 35 of this title, under chapter 106 or 107 of title 10, or under the Hostage Relief Act of 1980 (Public Law 96–449; 5 U.S.C. 5561 note) may not receive assistance under two or more of such programs concurrently but shall elect (in such form and manner as the Secretary may prescribe) under which program to receive educational assistance."],[0,"(2) An individual entitled to educational assistance under chapter 34 of this title may not receive assistance under this chapter before January 1, 1990."],[0,"(b) A period of service counted for purposes of repayment under chapter 109 of title 10 of an education loan may not also be counted for purposes of entitlement to educational assistance under this chapter."],[0,"(c) An individual who serves in the Selected Reserve may not receive credit for such service under two or more of the programs established by this chapter, chapter 33 of this title, and chapters 1606 and 1607 of title 10 but shall elect (in such form and manner as the Secretary may prescribe) the program to which such service is to be credited."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3033?type=usc&year=mostrecent&link-type=html"},"head":"§3033. Bar to duplication of educational assistance benefits","tname":"Veterans' Benefits","by":{"0":"11","2":"14"}},{"t":"usc","label":"38 U.S.C. § 3201","url":"https://www.law.cornell.edu/uscode/text/38/3201","by":{"0":"7"}},{"t":"usc","label":"38 U.S.C. § 3231","url":"https://www.law.cornell.edu/uscode/text/38/3231","by":{"0":"11, 12, 13"}},{"t":"usc","label":"38 U.S.C. § 3301","url":"https://www.law.cornell.edu/uscode/text/38/3301","stext":{"head":"§3301. Definitions","paras":[[0,"In this chapter:"],[1,"(1) The term \"active duty\" has the meanings as follows (subject to the limitations specified in sections 3002(6) and 3311(b)):"],[2,"(A) In the case of members of the regular components of the Armed Forces, the meaning given such term in section 101(21)(A)."],[2,"(B) In the case of members of the reserve components of the Armed Forces, service on active duty under a call or order to active duty under section 688, 12301(a), 12301(d), 12301(g), 12301(h), 12302, 12304, 12304a, or 12304b of title 10 or section 712 1 of title 14."],[2,"(C) In the case of a member of the Army National Guard of the United States or Air National Guard of the United States, in addition to service described in subparagraph (B), full-time service—"],[3,"(i) in the National Guard of a State for the purpose of organizing, administering, recruiting, instructing, or training the National Guard; or"],[3,"(ii) in the National Guard under section 502(f) of title 32 when authorized by the President or the Secretary of Defense for the purpose of responding to a national emergency declared by the President and supported by Federal funds."],[1,"(2) The term \"emergency situation\" has the meaning given such term in section 3601 of this title."],[1,"(3) The term \"entry level and skill training\" means the following:"],[2,"(A) In the case of members of the Army, Basic Combat Training and Advanced Individual Training or One Station Unit Training."],[2,"(B) In the case of members of the Navy, Recruit Training (or Boot Camp) and Skill Training (or so-called \"A\" School)."],[2,"(C) In the case of members of the Air Force or the Space Force, Basic Military Training and Technical Training."],[2,"(D) In the case of members of the Marine Corps, Recruit Training and Marine Corps Training (or School of Infantry Training)."],[2,"(E) In the case of members of the Coast Guard, Basic Training and Skill Training (or so-called \"A\" School)."],[1,"(4) The term \"program of education\" has the meaning given such term in section 3002, except to the extent otherwise provided in section 3313."],[1,"(5) The term \"Secretary of Defense\" means the Secretary of Defense, except that the term means the Secretary of Homeland Security with respect to the Coast Guard when it is not operating as a service in the Navy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3301?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§3301. Definitions","tname":"Veterans' Benefits","by":{"0":"6, 14, 15, 17, 48","1":"2","2":"2, 13, 22"}},{"t":"usc","label":"38 U.S.C. § 3311","url":"https://www.law.cornell.edu/uscode/text/38/3311","subs":["(b)","(b)(1)(A)"],"stext":{"head":"§3311. Educational assistance for service in the Armed Forces commencing on or after September 11, 2001: entitlement","paras":[[0,"(a) Entitlement.—Subject to subsections (d) and (e), each individual described in subsection (b) is entitled to educational assistance under this chapter."],[0,"(b) Covered Individuals.—An individual described in this subsection is any individual as follows:"],[1,"(1) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 36 months on active duty in the Armed Forces (including service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty; or"],[3,"(ii) is discharged or released from active duty as described in subsection (c)."],[1,"(2) An individual—"],[2,"(A) who—"],[3,"(i) commencing on or after September 11, 2001, serves at least 30 continuous days on active duty in the Armed Forces; and"],[3,"(ii) after completion of service described in clause (i), is discharged or released from active duty in the Armed Forces for a service-connected disability or by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10); or"],[2,"(B) who—"],[3,"(i) commencing on or after September 11, 2001, completes at least 30 continuous days of service described in subsection (d)(1) or (2); and"],[3,"(ii) after completion of service described in clause (i), is discharged or released by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10)."],[1,"(3) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 30 months, but less than 36 months, on active duty in the Armed Forces (including service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty for an aggregate of less than 36 months; or"],[3,"(ii) before completion of service on active duty of an aggregate of 36 months, is discharged or released from active duty as described in subsection (c)."],[1,"(4) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 24 months, but less than 30 months, on active duty in the Armed Forces (including service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty for an aggregate of less than 30 months; or"],[3,"(ii) before completion of service on active duty of an aggregate of 30 months, is discharged or released from active duty as described in subsection (c)."],[1,"(5) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 18 months, but less than 24 months, on active duty in the Armed Forces (excluding service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty for an aggregate of less than 24 months; or"],[3,"(ii) before completion of service on active duty of an aggregate of 24 months, is discharged or released from active duty as described in subsection (c)."],[1,"(6) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 6 months, but less than 18 months, on active duty in the Armed Forces (excluding service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty for an aggregate of less than 18 months; or"],[3,"(ii) before completion of service on active duty of an aggregate of 18 months, is discharged or released from active duty as described in subsection (c)."],[1,"(7) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 90 days, but less than 6 months, on active duty in the Armed Forces (excluding service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty for an aggregate of less than 6 months; or"],[3,"(ii) before completion of service on active duty of an aggregate of 6 months, is discharged or released from active duty as described in subsection (c)."],[1,"(8) An individual who is the child or spouse of a person who, on or after September 11, 2001, dies in line of duty while serving on active duty as a member of the Armed Forces."],[1,"(9) An individual who is the child or spouse of a person who, on or after September 11, 2001, dies in line of duty while serving on duty other than active duty as a member of the Armed Forces."],[1,"(10) An individual who is the child or spouse of a member of the Selected Reserve who dies on or after September 11, 2001, while a member of the Selected Reserve from a service-connected disability."],[1,"(11) An individual who is awarded the Purple Heart for service in the Armed Forces occurring on or after September 11, 2001, and continues to serve on active duty in the Armed Forces or is discharged or released from active duty as described in subsection (c)."],[0,"(c) Covered Discharges and Releases.—A discharge or release from active duty of an individual described in this subsection is a discharge or release as follows:"],[1,"(1) A discharge from active duty in the Armed Forces with an honorable discharge."],[1,"(2) A release after service on active duty in the Armed Forces characterized by the Secretary concerned as honorable service and placement on the retired list, transfer to the Fleet Reserve or Fleet Marine Corps Reserve, or placement on the temporary disability retired list."],[1,"(3) A release from active duty in the Armed Forces for further service in a reserve component of the Armed Forces, or for further service in the Space Force in a space force active status not on sustained duty under section 20105 of title 10, after service on active duty characterized by the Secretary concerned as honorable service."],[1,"(4) A discharge or release from active duty in the Armed Forces after service on active duty in the Armed Forces characterized by the Secretary concerned as honorable service for—"],[2,"(A) a medical condition which preexisted the service of the individual as described in the applicable paragraph of subsection (b) and which the Secretary determines is not service-connected;"],[2,"(B) hardship; or"],[2,"(C) a physical or mental condition that was not characterized as a disability and did not result from the individual's own willful misconduct but did interfere with the individual's performance of duty, as determined by the Secretary concerned in accordance with regulations prescribed by the Secretary of Defense."],[0,"(d) Prohibition on Treatment of Certain Service as Period of Active Duty.—Except as provided in subsection (b)(2)(B), the following periods of service shall not be considered a part of the period of active duty on which an individual's entitlement to educational assistance under this chapter is based:"],[1,"(1) A period of service on active duty of an officer pursuant to an agreement under section 2107(b) of title 10."],[1,"(2) A period of service on active duty of an officer pursuant to an agreement under section 7448, 8459, or 9448 of title 10 or section 182 1 of title 14."],[1,"(3) A period of service that is terminated because of a defective enlistment and induction based on—"],[2,"(A) the individual's being a minor for purposes of service in the Armed Forces;"],[2,"(B) an erroneous enlistment or induction; or"],[2,"(C) a defective enlistment agreement."],[0,"(e) Treatment of Individuals Entitled Under Multiple Provisions.—In the event an individual entitled to educational assistance under this chapter is entitled by reason of both paragraphs (4) and (5) of subsection (b), the individual shall be treated as being entitled to educational assistance under this chapter by reason of paragraph (5) of subsection (b)."],[0,"(f) Marine Gunnery Sergeant John David Fry Scholarship.—"],[1,"(1) In general.—Educational assistance payable by reason of paragraphs (8), (9), and (10) of subsection (b) shall be known as the \"Marine Gunnery Sergeant John David Fry scholarship\"."],[1,"(2) Election on receipt of certain benefits.—Except as provided in paragraph (3), a surviving spouse entitled to assistance under subsection (a) pursuant to paragraphs (8), (9), and (10) of subsection (b) who is also entitled to educational assistance under chapter 35 of this title may not receive assistance under both this section and such chapter, but shall make an irrevocable election (in such form and manner as the Secretary may prescribe) under which section or chapter to receive educational assistance."],[1,"(3) Exception for certain elections.—"],[2,"(A) In general.—An election made under paragraph (2) by a spouse described in subparagraph (B) may not be treated as irrevocable if such election occurred before the date of the enactment of this paragraph."],[2,"(B) Eligible surviving spouse.—A spouse described in this subparagraph is an individual—"],[3,"(i) who is entitled to assistance under subsection (a) pursuant to paragraphs (8), (9), and (10) of subsection (b); and"],[3,"(ii) who was the spouse of a member of the Armed Forces who died during the period beginning on September 11, 2001, and ending on December 31, 2005."],[1,"(4) Definition of child.—For purposes of paragraphs (8), (9), and (10) of subsection (b), the term \"child\" includes a married individual or an individual who is above the age of twenty-three years."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3311?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§3311. Educational assistance for service in the Armed Forces commencing on or after September 11, 2001: entitlement","tname":"Veterans' Benefits","by":{"0":"3, 16, 17, 39, 41, 47, 49","1":"2, 3, 19","2":"1, 4"}},{"t":"usc","label":"38 U.S.C. § 3312","url":"https://www.law.cornell.edu/uscode/text/38/3312","subs":["(a)"],"stext":{"head":"§3312. Educational assistance: duration","paras":[[0,"(a) In General.—Subject to section 3695 and except as provided in subsections (b) and (c), an individual entitled to educational assistance under this chapter is entitled to a number of months of educational assistance under section 3313 equal to 36 months."],[0,"(b) Continuing Receipt.—The receipt of educational assistance under section 3313 by an individual entitled to educational assistance under this chapter is subject to the provisions of section 3321(b)(2)."],[0,"(c) Discontinuation of Education for Active Duty.—"],[1,"(1) In general.—Any payment of educational assistance described in paragraph (2) shall not—"],[2,"(A) be charged against any entitlement to educational assistance of the individual concerned under this chapter; or"],[2,"(B) be counted against the aggregate period for which section 3695 limits the individual's receipt of educational assistance under this chapter."],[1,"(2) Description of payment of educational assistance.—Subject to paragraph (3), the payment of educational assistance described in this paragraph is the payment of such assistance to an individual for pursuit of a course or courses under this chapter if the Secretary finds that the individual—"],[2,"(A)(i) in the case of an individual not serving on active duty, had to discontinue such course pursuit as a result of being called or ordered to serve on active duty under section 688, 12301(a), 12301(d), 12301(g), 12302, or 12304 of title 10; or"],[2,"(ii) in the case of an individual serving on active duty, had to discontinue such course pursuit as a result of being ordered to a new duty location or assignment or to perform an increased amount of work; and"],[2,"(B) failed to receive credit or lost training time toward completion of the individual's approved education, professional, or vocational objective as a result of having to discontinue, as described in subparagraph (A), the individual's course pursuit."],[1,"(3) Period for which payment not charged.—The period for which, by reason of this subsection, educational assistance is not charged against entitlement or counted toward the applicable aggregate period under section 3695 of this title shall not exceed the portion of the period of enrollment in the course or courses from which the individual failed to receive credit or with respect to which the individual lost training time, as determined under paragraph (2)(B)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3312?type=usc&year=mostrecent&link-type=html"},"head":"§3312. Educational assistance: duration","tname":"Veterans' Benefits","by":{"0":"11, 17","1":"2, 28","2":"4"}},{"t":"usc","label":"38 U.S.C. § 3313","url":"https://www.law.cornell.edu/uscode/text/38/3313","subs":["(a)"],"stext":{"head":"§3313. Educational assistance: amount; payment","paras":[[0,"(a) Payment.—The Secretary shall pay to each individual entitled to educational assistance under this chapter who is pursuing an approved program of education (other than a program covered by subsections (e) and (f)) the amounts specified in subsection (c) to meet the expenses of such individual's subsistence, tuition, fees, and other educational costs for pursuit of such program of education."],[0,"(b) Approved Programs of Education.—A program of education is an approved program of education for purposes of this chapter if the program of education is approved for purposes of chapter 30 (including approval by the State approving agency concerned)."],[0,"(c) Programs of Education Leading to a Degree Pursued at Institutions of Higher Learning on More Than Half-time Basis.—The amounts payable under this subsection for pursuit of an approved program of education leading to a degree at an institution of higher learning (as that term is defined in section 3452(f)) are amounts as follows:"],[1,"(1) In the case of an individual entitled to educational assistance under this chapter by reason of paragraph (1), (2), (8), (9), (10), or (11) of section 3311(b), amounts as follows:"],[2,"(A) An amount equal to the following:"],[3,"(i) In the case of a program of education pursued at a public institution of higher learning, the actual net cost for in-State tuition and fees assessed by the institution for the program of education after the application of—"],[4,"(I) any waiver of, or reduction in, tuition and fees; and"],[4,"(II) any scholarship, or other Federal, State, institutional, or employer-based aid or assistance (other than loans and any funds provided under section 401(b) of the Higher Education Act of 1965 (20 U.S.C. 1070a(b))) that is provided directly to the institution and specifically designated for the sole purpose of defraying tuition and fees."],[3,"(ii) In the case of a program of education pursued at a non-public or foreign institution of higher learning, the lesser of—"],[4,"(I) the actual net cost for tuition and fees assessed by the institution for the program of education after the application of—"],[5,"(aa) any waiver of, or reduction in, tuition and fees; and"],[5,"(bb) any scholarship, or other Federal, State, institutional, or employer-based aid or assistance (other than loans and any funds provided under section 401(b) of the Higher Education Act of 1965) that is provided directly to the institution and specifically designated for the sole purpose of defraying tuition and fees; or"],[4,"(II) the amount equal to—"],[5,"(aa) for the academic year beginning on August 1, 2011, $17,500; or"],[5,"(bb) for an academic year beginning on any subsequent August 1, the amount for the previous academic year beginning on August 1 under this subclause, as increased by the percentage increase equal to the most recent percentage increase determined under section 3015(h)."],[2,"(B) A monthly stipend in an amount as follows:"],[3,"(i) Except as provided in clauses (ii) and (iii), for each month an individual pursues a program of education on more than a half-time basis, a monthly housing stipend equal to the product of—"],[4,"(I) the monthly amount of the basic allowance for housing payable under section 403 of title 37 for a member with dependents in pay grade E–5 residing in the military housing area that encompasses all or the majority portion of the ZIP code area in which is located the campus of the institution of higher learning where the individual physically participates in a majority of classes, multiplied by"],[4,"(II) the lesser of—"],[5,"(aa) 1.0; or"],[5,"(bb) the number of course hours borne by the individual in pursuit of the program of education, divided by the minimum number of course hours required for full-time pursuit of the program of education, rounded to the nearest multiple of 10."],[3,"(ii) In the case of an individual pursuing a program of education at a foreign institution of higher learning on more than a half-time basis, for each month the individual pursues the program of education, a monthly housing stipend equal to the product of—"],[4,"(I) the national average of the monthly amount of the basic allowance for housing payable under section 403 of title 37 for a member with dependents in pay grade E–5, multiplied by"],[4,"(II) the lesser of—"],[5,"(aa) 1.0; or"],[5,"(bb) the number of course hours borne by the individual in pursuit of the program of education, divided by the minimum number of course hours required for full-time pursuit of the program of education, rounded to the nearest multiple of 10."],[3,"(iii) In the case of an individual pursuing a program of education solely through distance learning on more than a half-time basis, a monthly housing stipend equal to 50 percent of the amount payable under clause (ii) if the individual were otherwise entitled to a monthly housing stipend under that clause for pursuit of the program of education."],[3,"(iv) For the first month of each quarter, semester, or term, as applicable, of the program of education pursued by the individual, a lump sum amount for books, supplies, equipment, and other educational costs with respect to such quarter, semester, or term in the amount equal to—"],[4,"(I) $1,000, multiplied by"],[4,"(II) the fraction which is the portion of a complete academic year under the program of education that such quarter, semester, or term constitutes."],[1,"(2) In the case of an individual entitled to educational assistance under this chapter by reason of section 3311(b)(3), amounts equal to 90 percent of the amounts that would be payable to the individual under paragraph (1) for the program of education if the individual were entitled to amounts for the program of education under paragraph (1) rather than this paragraph."],[1,"(3) In the case of an individual entitled to educational assistance under this chapter by reason of section 3311(b)(4), amounts equal to 80 percent of the amounts that would be payable to the individual under paragraph (1) for the program of education if the individual were entitled to amounts for the program of education under paragraph (1) rather than this paragraph."],[1,"(4) In the case of an individual entitled to educational assistance under this chapter by reason of section 3311(b)(5), amounts equal to 70 percent of the amounts that would be payable to the individual under paragraph (1) for the program of education if the individual were entitled to amounts for the program of education under paragraph (1) rather than this paragraph."],[1,"(5) In the case of an individual entitled to educational assistance under this chapter by reason of section 3311(b)(6), amounts equal to 60 percent of the amounts that would be payable to the individual under paragraph (1) for the program of education if the individual were entitled to amounts for the program of education under paragraph (1) rather than this paragraph."],[1,"(6) In the case of an individual entitled to educational assistance under this chapter by reason of section 3311(b)(7),1 amounts equal to 50 percent of the amounts that would be payable to the individual under paragraph (1) for the program of education if the individual were entitled to amounts for the program of education under paragraph (1) rather than this paragraph."],[0,"(d) Frequency of Payment.—"],[1,"(1) Quarter, semester, or term payments.—Payment of the amounts payable under subsection (c)(1)(A), and of similar amounts payable under paragraphs (2) through (6) of subsection (c), for pursuit of a program of education shall be made for the entire quarter, semester, or term, as applicable, of the program of education."],[1,"(2) Monthly payments.—Payment of the amount payable under subsection (c)(1)(B), and of similar amounts payable under paragraphs (2) through (6) of subsection (c), for pursuit of a program of education shall be made on a monthly basis."],[1,"(3) Regulations.—The Secretary shall prescribe in regulations methods for determining the number of months (including fractions thereof) of entitlement of an individual to educational assistance under this chapter that are chargeable under this chapter for an advance payment of amounts under paragraphs (1) and (2) for pursuit of a program of education on a quarter, semester, term, or other basis."],[0,"(e) Programs of Education Leading to a Degree Pursued on Active Duty for a Period of More Than 30 Days on More Than Half-time Basis.—"],[1,"(1) In general.—Educational assistance is payable under this chapter for pursuit of an approved program of education leading to a degree while on active duty for a period of more than 30 days."],[1,"(2) Amount of assistance.—The amounts of educational assistance payable under this chapter to an individual pursuing a program of education leading to a degree while on active duty for a period of more than 30 days are as follows:"],[2,"(A) Subject to subparagraph (C), an amount equal to the lesser of—"],[3,"(i) in the case of a program of education pursued at a public institution of higher learning, the actual net cost for in-State tuition and fees assessed by the institution for the program of education after the application of—"],[4,"(I) any waiver of, or reduction in, tuition and fees; and"],[4,"(II) any scholarship, or other Federal, State, institutional, or employer-based aid or assistance (other than loans and any funds provided under section 401(b) of the Higher Education Act of 1965 (20 U.S.C. 1070a(b))) that is provided directly to the institution and specifically designated for the sole purpose of defraying tuition and fees;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3313?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3313. Educational assistance: amount; payment","tname":"Veterans' Benefits","by":{"0":"15, 16, 49","1":"3, 3"}},{"t":"usc","label":"38 U.S.C. § 3315","url":"https://www.law.cornell.edu/uscode/text/38/3315","by":{"0":"15, 49"}},{"t":"usc","label":"38 U.S.C. § 3316","url":"https://www.law.cornell.edu/uscode/text/38/3316","by":{"0":"15, 49, 58"}},{"t":"usc","label":"38 U.S.C. § 3317","url":"https://www.law.cornell.edu/uscode/text/38/3317","by":{"0":"15, 49"}},{"t":"usc","label":"38 U.S.C. § 3318","url":"https://www.law.cornell.edu/uscode/text/38/3318","by":{"0":"15, 49"}},{"t":"usc","label":"38 U.S.C. § 3319","url":"https://www.law.cornell.edu/uscode/text/38/3319","subs":["(h)(2)(A)","(h)(7)"],"stext":{"head":"§3319. Authority to transfer unused education benefits to family members","paras":[[0,"(a) In General.—"],[1,"(1) Subject to the provisions of this section, the Secretary concerned may permit an individual described in subsection (b) who is entitled to educational assistance under this chapter to elect to transfer to one or more of the dependents specified in subsection (c) a portion of such individual's entitlement to such assistance, subject to the limitation under subsection (d)."],[1,"(2) The purpose of the authority in paragraph (1) is to promote recruitment and retention in the uniformed services. The Secretary concerned may exercise the authority for that purpose when authorized by the Secretary of Defense in the national security interests of the United States."],[0,"(b) Eligible Individuals.—An individual referred to in subsection (a) is any member of the uniformed services who, at the time of the approval of the individual's request to transfer entitlement to educational assistance under this section, has completed at least—"],[1,"(1) six years of service in the Armed Forces and enters into an agreement to serve at least four more years as a member of the uniformed services; or"],[1,"(2) the years of service as determined in regulations pursuant to subsection (j)."],[0,"(c) Eligible Dependents.—"],[1,"(1) Transfer.—An individual approved to transfer an entitlement to educational assistance under this section may transfer the individual's entitlement to an eligible dependent or a combination of eligible dependents."],[1,"(2) Definition of eligible dependent.—For purposes of this subsection, the term \"eligible dependent\" has the meaning given the term \"dependent\" under subparagraphs (A), (I), and (D) of section 1072(2) of title 10."],[0,"(d) Limitation on Months of Transfer.—The total number of months of entitlement transferred by a individual under this section may not exceed 36 months. The Secretary of Defense may prescribe regulations that would limit the months of entitlement that may be transferred under this section to no less than 18 months."],[0,"(e) Designation of Transferee.—An individual transferring an entitlement to educational assistance under this section shall—"],[1,"(1) designate the dependent or dependents to whom such entitlement is being transferred; and"],[1,"(2) designate the number of months of such entitlement to be transferred to each such dependent."],[0,"(f) Time for Transfer; Revocation and Modification.—"],[1,"(1) Time for transfer.—Subject to the time limitation for use of entitlement under section 3321, and except as provided in subsection (k) or (l), an individual approved to transfer entitlement to educational assistance under this section may transfer such entitlement only while serving as a member of the Armed Forces when the transfer is executed."],[1,"(2) Modification or revocation.—"],[2,"(A) In general.—An individual transferring entitlement under this section may modify or revoke at any time the transfer of any unused portion of the entitlement so transferred."],[2,"(B) Notice.—The modification or revocation of the transfer of entitlement under this paragraph shall be made by the submittal of written notice of the action to both the Secretary concerned and the Secretary of Veterans Affairs."],[1,"(3) Prohibition on treatment of transferred entitlement as marital property.—Entitlement transferred under this section may not be treated as marital property, or the asset of a marital estate, subject to division in a divorce or other civil proceeding."],[0,"(g) Commencement of Use.—A dependent to whom entitlement to educational assistance is transferred under this section may not commence the use of the transferred entitlement until—"],[1,"(1) in the case of entitlement transferred to a spouse, the completion by the individual making the transfer of at least—"],[2,"(A) six years of service in the Armed Forces; or"],[2,"(B) the years of service as determined in regulations pursuant to subsection (j); or"],[1,"(2) in the case of entitlement transferred to a child, both—"],[2,"(A) the completion by the individual making the transfer of at least—"],[3,"(i) ten years of service in the Armed Forces; or"],[3,"(ii) the years of service as determined in regulations pursuant to subsection (j); and"],[2,"(B) either—"],[3,"(i) the completion by the child of the requirements of a secondary school diploma (or equivalency certificate); or"],[3,"(ii) the attainment by the child of 18 years of age."],[0,"(h) Additional Administrative Matters.—"],[1,"(1) Use.—The use of any entitlement to educational assistance transferred under this section shall be charged against the entitlement of the individual making the transfer at the rate of one month for each month of transferred entitlement that is used."],[1,"(2) Nature of transferred entitlement.—Except as provided under subsection (e)(2) and subject to paragraphs (5) and (6)—"],[2,"(A) in the case of entitlement transferred to a spouse under this section, the spouse is entitled to educational assistance under this chapter in the same manner as the individual from whom the entitlement was transferred; or"],[2,"(B) in the case of entitlement transferred to a child under this section, the child is entitled to educational assistance under this chapter in the same manner as the individual from whom the entitlement was transferred as if the individual were not on active duty."],[1,"(3) Rate of payment.—The monthly rate of educational assistance payable to a dependent to whom entitlement referred to in paragraph (2) is transferred under this section shall be payable—"],[2,"(A) in the case of a spouse, at the same rate as such entitlement would otherwise be payable under this chapter to the individual making the transfer; or"],[2,"(B) in the case of a child, at the same rate as such entitlement would otherwise be payable under this chapter to the individual making the transfer as if the individual were not on active duty."],[1,"(4) Death of transferor.—"],[2,"(A) In general.—The death of an individual transferring an entitlement under this section shall not affect the use of the entitlement by the dependent to whom the entitlement is transferred."],[2,"(B) Death prior to transfer to designated transferees.—(i) In the case of an eligible individual whom the Secretary has approved to transfer the individual's entitlement under this section who, at the time of death, is entitled to educational assistance under this chapter and has designated a transferee or transferees under subsection (e) but has not transferred all of such entitlement to such transferee or transferees, the Secretary shall transfer the entitlement of the individual under this section by evenly distributing the amount of such entitlement between all such transferees who would not be precluded from using some or all of the transferred benefits due to the expiration of time limitations found in paragraph (5) of this subsection or section 3321 of this title, notwithstanding the limitations under subsection (f)."],[2,"(ii) If a transferee cannot use all of the transferred benefits under clause (i) because of expiration of a time limitation, the unused benefits will be distributed among the other designated transferees who would not be precluded from using some or all of the transferred benefits due to expiration of time limitations found in paragraph (5) of this subsection or section 3321 of this title, unless or until there are no transferees who would not be precluded from using the transferred benefits because of expiration of a time limitation."],[1,"(5) Limitation on age of use by child transferees.—"],[2,"(A) In general.—A child to whom entitlement is transferred under this section may use the benefits transferred without regard to the 15-year delimiting date specified in section 3321, but may not, except as provided in subparagraph (B) or (C), use any benefits so transferred after attaining the age of 26 years."],[2,"(B) Primary caregivers of seriously injured members of the armed forces and veterans.—"],[3,"(i) In general.—Subject to clause (ii), in the case of a child who, before attaining the age of 26 years, is prevented from pursuing a chosen program of education by reason of acting as the primary provider of personal care services for a veteran or member of the Armed Forces under section 1720G(a), the child may use the benefits beginning on the date specified in clause (iii) for a period whose length is specified in clause (iv)."],[3,"(ii) Inapplicability for revocation.—Clause (i) shall not apply with respect to the period of an individual as a primary provider of personal care services if the period concludes with the revocation of the individual's designation as such a primary provider under section 1720G(a)(7)(D)."],[3,"(iii) Date for commencement of use.—The date specified in this clause for the beginning of the use of benefits by a child under clause (i) is the later of—"],[4,"(I) the date on which the child ceases acting as the primary provider of personal care services for the veteran or member concerned as described in clause (i);"],[4,"(II) the date on which it is reasonably feasible, as determined under regulations prescribed by the Secretary, for the child to initiate or resume the use of benefits; or"],[4,"(III) the date on which the child attains the age of 26 years."],[3,"(iv) Length of use.—The length of the period specified in this clause for the use of benefits by a child under clause (i) is the length equal to the length of the period that—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3319?type=usc&year=mostrecent&link-type=html"},"head":"§3319. Authority to transfer unused education benefits to family members","tname":"Veterans' Benefits","by":{"0":"55, 57","1":"3, 30, 30, 31","2":"23"}},{"t":"usc","label":"38 U.S.C. § 3322","url":"https://www.law.cornell.edu/uscode/text/38/3322","subs":["(a)","(b)","(d)","(h)","(h)(1)"],"stext":{"head":"§3322. Bar to duplication of educational assistance benefits","paras":[[0,"(a) In General.—An individual entitled to educational assistance under this chapter who is also eligible for educational assistance under chapter 30, 31, 32, or 35 of this title, chapter 107, 1606, or 1607 or section 510 of title 10, or the provisions of the Hostage Relief Act of 1980 (Public Law 96–449; 5 U.S.C. 5561 note) may not receive assistance under two or more such programs concurrently, but shall elect (in such form and manner as the Secretary may prescribe) under which chapter or provisions to receive educational assistance."],[0,"(b) Inapplicability of Service Treated Under Educational Loan Repayment Programs.—A period of service counted for purposes of repayment of an education loan under chapter 109 of title 10 may not be counted as a period of service for entitlement to educational assistance under this chapter."],[0,"(c) Service in Selected Reserve.—An individual who serves in the Selected Reserve may receive credit for such service under only one of this chapter, chapter 30 of this title, and chapters 1606 and 1607 of title 10, and shall elect (in such form and manner as the Secretary may prescribe) under which chapter such service is to be credited."],[0,"(d) Additional Coordination Matters.—In the case of an individual entitled to educational assistance under chapter 30, 31, 32, or 35 of this title, chapter 107, 1606, or 1607 of title 10, or the provisions of the Hostage Relief Act of 1980, or making contributions toward entitlement to educational assistance under chapter 30 of this title, as of August 1, 2009, coordination of entitlement to educational assistance under this chapter, on the one hand, and such chapters or provisions, on the other, shall be governed by the provisions of section 5003(c) of the Post-9/11 Veterans Educational Assistance Act of 2008."],[0,"(e) Bar To Concurrent Receipt of Transferred Education Benefits and Marine Gunnery Sergeant John David Fry Scholarship Assistance.—An individual entitled to educational assistance under both section 3319 and paragraph (8), (9), or (10) of section 3311 of this title may not receive assistance under both provisions concurrently, but shall elect (in such form and manner as the Secretary may prescribe) under which provision to receive educational assistance."],[0,"(f) Bar To Receipt of Compensation and Pension and Marine Gunnery Sergeant John David Fry Scholarship Assistance.—The commencement of a program of education under paragraph (8), (9), or (10) of section 3311 of this title shall be a bar to the following:"],[1,"(1) Subsequent payments of dependency and indemnity compensation or pension based on the death of a parent to an eligible person over the age of 18 years by reason of pursuing a course in an educational institution."],[1,"(2) Increased rates, or additional amounts, of compensation, dependency and indemnity compensation, or pension because of such a person, whether eligibility is based upon the death of the parent."],[0,"(g) Bar To Concurrent Receipt of Transferred Education Benefits.—A spouse or child who is entitled to educational assistance under this chapter based on a transfer of entitlement from more than one individual under section 3319 may not receive assistance based on transfers from more than one such individual concurrently, but shall elect (in such form and manner as the Secretary may prescribe) under which source to utilize such assistance at any one time."],[0,"(h) Bar To Duplication of Eligibility Based on a Single Event or Period of Service.—"],[1,"(1) Active-duty service.—An individual with qualifying service in the Armed Forces that establishes eligibility on the part of such individual for educational assistance under this chapter, chapter 30 or 32 of this title, and chapter 1606 or 1607 of title 10, shall elect (in such form and manner as the Secretary may prescribe) under which authority such service is to be credited."],[1,"(2) Eligibility for educational assistance based on parent's service.—A child of a member of the Armed Forces who, on or after September 11, 2001, dies in the line of duty while serving on active duty, who is eligible for educational assistance under either chapter 35 or paragraph (8), (9), or (10) of section 3311 of this title based on the parent's death may not receive such assistance under both this chapter and chapter 35 of this title, but shall elect (in such form and manner as the Secretary may prescribe) under which chapter to receive such assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3322?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§3322. Bar to duplication of educational assistance benefits","tname":"Veterans' Benefits","by":{"0":"11, 19, 20, 40, 50, 52, 53, 55, 60","1":"3, 30, 3, 30, 3, 30, 3, 30, 3, 30, 3, 30, 3, 30","2":"4, 13, 15, 16, 18"}},{"t":"usc","label":"38 U.S.C. § 3327","url":"https://www.law.cornell.edu/uscode/text/38/3327","subs":["(a)","(a)(1)","(a)(1)(A)","(a)(1)(B)","(a)(1)(E)","(a)(2)","(d)","(d)(1)","(d)(2)","(d)(2)(A)","(g)","(h)(1)","(i)"],"stext":{"head":"§3327. Election to receive educational assistance","paras":[[0,"(a) Individuals Eligible To Elect Participation in Post-9/11 Educational Assistance.—An individual may elect to receive educational assistance under this chapter if such individual—"],[1,"(1) as of August 1, 2009—"],[2,"(A) is entitled to basic educational assistance under chapter 30 of this title and has used, but retains unused, entitlement under that chapter;"],[2,"(B) is entitled to educational assistance under chapter 107, 1606, or 1607 of title 10 and has used, but retains unused, entitlement under the applicable chapter;"],[2,"(C) is entitled to basic educational assistance under chapter 30 of this title but has not used any entitlement under that chapter;"],[2,"(D) is entitled to educational assistance under chapter 107, 1606, or 1607 of title 10 but has not used any entitlement under such chapter;"],[2,"(E) is a member of the Armed Forces who is eligible for receipt of basic educational assistance under chapter 30 of this title and is making contributions toward such assistance under section 3011(b) or 3012(c) of this title; or"],[2,"(F) is a member of the Armed Forces who is not entitled to basic educational assistance under chapter 30 of this title by reason of an election under section 3011(c)(1) or 3012(d)(1) of this title; and"],[1,"(2) as of the date of the individual's election under this paragraph, meets the requirements for entitlement to educational assistance under this chapter."],[0,"(b) Cessation of Contributions Toward GI Bill.—Effective as of the first month beginning on or after the date of an election under subsection (a) of an individual described by paragraph (1)(E) of that subsection, the obligation of the individual to make contributions under section 3011(b) or 3012(c) of this title, as applicable, shall cease, and the requirements of such section shall be deemed to be no longer applicable to the individual."],[0,"(c) Revocation of Remaining Transferred Entitlement.—"],[1,"(1) Election to revoke.—If, on the date an individual described in paragraph (1)(A) or (1)(C) of subsection (a) makes an election under that subsection, a transfer of the entitlement of the individual to basic educational assistance under section 3020 of this title is in effect and a number of months of the entitlement so transferred remain unutilized, the individual may elect to revoke all or a portion of the entitlement so transferred that remains unutilized."],[1,"(2) Availability of revoked entitlement.—Any entitlement revoked by an individual under this subsection shall no longer be available to the dependent to whom transferred, but shall be available to the individual instead for educational assistance under chapter 33 of this title in accordance with the provisions of this section."],[1,"(3) Availability of unrevoked entitlement.—Any entitlement described in paragraph (1) that is not revoked by an individual in accordance with that paragraph shall remain available to the dependent or dependents concerned in accordance with the current transfer of such entitlement under section 3020 of this title."],[0,"(d) Post-9/11 Educational Assistance.—"],[1,"(1) In general.—Subject to paragraph (2) and except as provided in subsection (e), an individual making an election under subsection (a) shall be entitled to educational assistance under this chapter in accordance with the provisions of this chapter, instead of basic educational assistance under chapter 30 of this title, or educational assistance under chapter 107, 1606, or 1607 of title 10, as applicable."],[1,"(2) Limitation on entitlement for certain individuals.—In the case of an individual making an election under subsection (a) who is described by paragraph (1)(A) of that subsection, the number of months of entitlement of the individual to educational assistance under this chapter shall be the number of months equal to—"],[2,"(A) the number of months of unused entitlement of the individual under chapter 30 of this title, as of the date of the election, plus"],[2,"(B) the number of months, if any, of entitlement revoked by the individual under subsection (c)(1)."],[0,"(e) Continuing Entitlement to Educational Assistance Not Available Under Post-9/11 Educational Assistance Program.—"],[1,"(1) In general.—In the event educational assistance to which an individual making an election under subsection (a) would be entitled under chapter 30 of this title, or chapter 107, 1606, or 1607 of title 10, as applicable, is not authorized to be available to the individual under the provisions of this chapter, the individual shall remain entitled to such educational assistance in accordance with the provisions of the applicable chapter."],[1,"(2) Charge for use of entitlement.—The utilization by an individual of entitlement under paragraph (1) shall be chargeable against the entitlement of the individual to educational assistance under this chapter at the rate of 1 month of entitlement under this chapter for each month of entitlement utilized by the individual under paragraph (1) (as determined as if such entitlement were utilized under the provisions of chapter 30 of this title, or chapter 107, 1606, or 1607 of title 10, as applicable)."],[0,"(f) Additional Post-9/11 Assistance for Members Having Made Contributions Toward GI Bill.—"],[1,"(1) Additional assistance.—In the case of an individual making an election under subsection (a) who is described by subparagraph (A), (C), or (E) of paragraph (1) of that subsection, the amount of educational assistance payable to the individual under this chapter as a monthly stipend payable under paragraph (1)(B) of section 3313(c) of this title, or under paragraphs (2) through (7) 1 of that section (as applicable), shall be the amount otherwise payable as a monthly stipend under the applicable paragraph increased by the amount equal to—"],[2,"(A) the total amount of contributions toward basic educational assistance made by the individual under section 3011(b) or 3012(c) of this title, as of the date of the election, multiplied by"],[2,"(B) the fraction—"],[3,"(i) the numerator of which is—"],[4,"(I) the number of months of entitlement to basic educational assistance under chapter 30 of this title remaining to the individual at the time of the election; plus"],[4,"(II) the number of months, if any, of entitlement under chapter 30 of this title revoked by the individual under subsection (c)(1); and"],[3,"(ii) the denominator of which is 36 months."],[1,"(2) Months of remaining entitlement for certain individuals.—In the case of an individual covered by paragraph (1) who is described by subsection (a)(1)(E), the number of months of entitlement to basic educational assistance remaining to the individual for purposes of paragraph (1)(B)(i)(II) shall be 36 months."],[1,"(3) Timing of payment.—The amount payable with respect to an individual under paragraph (1) shall be paid to the individual together with the last payment of the monthly stipend payable to the individual under paragraph (1)(B) of section 3313(c) of this title, or under paragraphs (2) through (7) 1 of that section (as applicable), before the exhaustion of the individual's entitlement to educational assistance under this chapter."],[0,"(g) Continuing Entitlement to Additional Assistance for Critical Skills or Specialty and Additional Service.—An individual making an election under subsection (a)(1) who, at the time of the election, is entitled to increased educational assistance under section 3015(d) of this title, or section 16131(i) of title 10, or supplemental educational assistance under subchapter III of chapter 30 of this title, shall remain entitled to such increased educational assistance or supplemental educational assistance in the utilization of entitlement to educational assistance under this chapter, in an amount equal to the quarter, semester, or term, as applicable, equivalent of the monthly amount of such increased educational assistance or supplemental educational assistance payable with respect to the individual at the time of the election."],[0,"(h) Alternative Election by Secretary.—"],[1,"(1) In general.—In the case of an individual who, on or after January 1, 2017, submits to the Secretary an election under this section that the Secretary determines is clearly against the interests of the individual, or who fails to make an election under this section, the Secretary may make an alternative election on behalf of the individual that the Secretary determines is in the best interests of the individual."],[1,"(2) Notice.—If the Secretary makes an election on behalf of an individual under this subsection, the Secretary shall notify the individual by not later than seven days after making such election and shall provide the individual with a 30-day period, beginning on the date of the individual's receipt of such notice, during which the individual may modify or revoke the election made by the Secretary on the individual's behalf. The Secretary shall include, as part of such notice, a clear statement of why the alternative election made by the Secretary is in the best interests of the individual as compared to the election submitted by the individual. The Secretary shall provide the notice required under this paragraph by electronic means whenever possible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3327?type=usc&year=mostrecent&link-type=html"},"op":35,"ar":1,"head":"§3327. Election to receive educational assistance","tname":"Veterans' Benefits","by":{"0":"3, 20, 21, 22, 23, 29, 42, 44, 45, 46, 51, 56, 57","1":"2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2","2":"4, 12, 14, 16, 20, 21"}},{"t":"usc","label":"38 U.S.C. § 3681","url":"https://www.law.cornell.edu/uscode/text/38/3681","by":{"0":"11"}},{"t":"usc","label":"38 U.S.C. § 3695","url":"https://www.law.cornell.edu/uscode/text/38/3695","subs":["(a)","(a)(3)","(a)(4)","(a)(5)","(a)(8)"],"stext":{"head":"§3695. Limitation on period of assistance under two or more programs","paras":[[0,"(a) The aggregate period for which any person may receive assistance under two or more of the provisions of law listed below may not exceed 48 months (or the part-time equivalent thereof):"],[1,"(1) Parts VII or VIII, Veterans Regulation numbered 1(a), as amended."],[1,"(2) Title II of the Veterans' Readjustment Assistance Act of 1952."],[1,"(3) The War Orphans' Educational Assistance Act of 1956."],[1,"(4) Chapters 30, 32, 33, 34, and 36."],[1,"(5) Chapters 107, 1606, 1607, and 1611 of title 10."],[1,"(6) Section 903 of the Department of Defense Authorization Act, 1981 (Public Law 96–342, 10 U.S.C. 2141 note)."],[1,"(7) The Hostage Relief Act of 1980 (Public Law 96–449, 5 U.S.C. 5561 note)."],[1,"(8) The Omnibus Diplomatic Security and Antiterrorism Act of 1986 (Public Law 99–399)."],[0,"(b) No person may receive assistance under chapter 31 of this title in combination with assistance under any of the provisions of law cited in subsection (a) of this section in excess of 48 months (or the part-time equivalent thereof) unless the Secretary determines that additional months of benefits under chapter 31 of this title are necessary to accomplish the purposes of a rehabilitation program (as defined in section 3101 of this title) in the individual case."],[0,"(c) The aggregate period for which any person may receive assistance under chapter 35 of this title, on the one hand, and any of the provisions of law referred to in subsection (a), on the other hand, may not exceed 81 months (or the part-time equivalent thereof)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3695?type=usc&year=mostrecent&link-type=html"},"op":10,"head":"§3695. Limitation on period of assistance under two or more programs","tname":"Veterans' Benefits","by":{"0":"3, 11, 40, 53, 60","1":"24, 33, 33, 33, 33, 33","2":"4, 21"}},{"t":"usc","label":"38 U.S.C. § 4100","url":"https://www.law.cornell.edu/uscode/text/38/4100","by":{"0":"7"}},{"t":"law","label":"Pub. L. No. 82-550","url":"https://www.govinfo.gov/link/statute/66/663","by":{"0":"6, 11, 12","2":"19, 23"}},{"t":"law","label":"Pub. L. No. 89-358","url":"https://www.govinfo.gov/link/statute/80/12","by":{"0":"7, 11, 12, 18"}},{"t":"law","label":"Pub. L. No. 90-631","url":"https://www.govinfo.gov/link/statute/82/1331","by":{"0":"11"}},{"t":"law","label":"Pub. L. No. 94-502","url":"https://www.govinfo.gov/link/statute/90/2383","by":{"0":"7"}},{"t":"reg","label":"38 C.F.R. § 21.4020","url":"https://www.ecfr.gov/current/title-38/section-21.4020","by":{"0":"27"}},{"t":"reg","label":"38 C.F.R. § 21.4022","url":"https://www.ecfr.gov/current/title-38/section-21.4022","by":{"0":"12, 24, 54","2":"23"}},{"t":"reg","label":"38 C.F.R. § 21.5022","url":"https://www.ecfr.gov/current/title-38/section-21.5022","by":{"0":"12"}},{"t":"reg","label":"38 C.F.R. § 21.7042","url":"https://www.ecfr.gov/current/title-38/section-21.7042","by":{"0":"12"}},{"t":"reg","label":"38 C.F.R. § 21.7143","url":"https://www.ecfr.gov/current/title-38/section-21.7143","by":{"0":"12, 24, 54","2":"23"}},{"t":"reg","label":"38 C.F.R. § 21.7540","url":"https://www.ecfr.gov/current/title-38/section-21.7540","by":{"0":"12"}},{"t":"reg","label":"38 C.F.R. § 21.7642","url":"https://www.ecfr.gov/current/title-38/section-21.7642","by":{"0":"12, 24"}},{"t":"reg","label":"38 C.F.R. § 21.9520","url":"https://www.ecfr.gov/current/title-38/section-21.9520","by":{"0":"27"}},{"t":"reg","label":"38 C.F.R. § 21.9635","url":"https://www.ecfr.gov/current/title-38/section-21.9635","by":{"0":"24, 54","2":"23"}},{"t":"reg","label":"38 C.F.R. § 21.9640","url":"https://www.ecfr.gov/current/title-38/section-21.9640","by":{"0":"15, 49"}},{"t":"reg","label":"38 C.F.R. § 21.9690","url":"https://www.ecfr.gov/current/title-38/section-21.9690","by":{"0":"24"}},{"t":"case","label":"Arellano v. McDonough","cite":"598 U.S. 1","y":2023,"id":"2022/21-432","sc":1,"sum":"The effective date of an award of service-related disability compensation to a veteran of the United States military determined pursuant to 38 U. S. C. §§5110(a)(1) and 5110(b)(1) is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31"}},{"t":"case","label":"Bates v. United States","cite":"522 U.S. 23","y":1997,"id":"1997/96-7185","sc":1,"sum":"The Court held that the specific intent to injure or defraud someone, whether the United States or another, is not an element of the misapplication of funds proscribed by section 1097(a).","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"op":3,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Epic Systems Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"op":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Lamie v. United States Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"sum":"The Court held that the Appropriations Clause of the Constitution explicitly states that no money can be paid from the Treasury unless specifically authorized by a statute. Since there is a statute that denies Richmond his benefits, and there is not one that provides an exception, the Court held that Richmond’s receipt of incorrect information cannot affect the non-payment of his benefits.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Pavelic & LeFlore v. Marvel Entertainment Group","cite":"493 U.S. 120","y":1989,"id":"1989/88-791","sc":1,"sum":"When read in the context of all of Rule ll's signature provisions, the phrase \"person who signed\" connotes the individual signer mentioned at the outset of the Rule and authorizes a court to impose a sanction only against that individual. That is so even when the individual explicitly signs on behalfof the firm, since it is only the signature \"in the attorney's individual name\" which complies with the Rule's …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Railroad Trainmen v. Baltimore & Ohio R.R.","cite":"331 U.S. 519","y":1947,"id":"scdb/1946-111","sc":1,"sum":"1. Under § 17 (11) of the Interstate Commerce Act, as amended by the Transportation Act of 1940, a union duly designated as the representative of employees of a railroad is given an absolute right, within the meaning of Rule 24 (a) (1) of the Federal Rules of Civil Procedure, to intervene in a suit brought under § 16 (12) to enjoin the railroad and its employees from violating an order of the Interstate Commerce …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"op":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"United Benefit Life Insurance Co. v. United States Life Insurance Co.","cite":"36 F.3d 1063","y":1994,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/36/1063/","by":{"1":"14"}},{"t":"const","label":"Article I, Section 8, Clause 12","text":"To raise and support Armies, but no Appropriation of Money to that Use shall be for a longer Term than two Years;","by":{"1":"28"}},{"t":"usc","label":"38 U.S.C. § 3020","url":"https://www.law.cornell.edu/uscode/text/38/3020","subs":["(h)(2)","(h)(6)"],"by":{"1":"3, 30, 30, 31"}},{"t":"usc","label":"38 U.S.C. § 3031","url":"https://www.law.cornell.edu/uscode/text/38/3031","by":{"1":"3"}},{"t":"usc","label":"38 U.S.C. § 3321","url":"https://www.law.cornell.edu/uscode/text/38/3321","by":{"1":"3"}},{"t":"usc","label":"38 U.S.C. § 1521","url":"https://www.law.cornell.edu/uscode/text/38/1521","by":{"1":"20"}},{"t":"reg","label":"Post-9/11 GI Bill, 73 Fed. Reg. 78,876","url":"https://www.govinfo.gov/link/fr/73/78876","by":{"1":"33","2":"24"}},{"t":"case","label":"Maine Cmty. Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"sum":"The Court held that the federal government has an obligation to pay the insurance carriers in this case for losses incurred under the \"Risk Corridors\" program of the Affordable Care Act as a result of their participation in the health care marketplace.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"2":"8"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Tr.","cite":"579 U.S. 115","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cnty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Sullivan v. Finkelstein","cite":"496 U.S. 617","y":1990,"id":"1989/89-504","sc":1,"sum":"The Secretary may immediately appeal a district court order effectively invalidating regulations limiting the kinds of inquiries that must be made to determine entitlement to disability insurance benefits and remanding a claim to the Secretary for consideration without those restrictions. Pp. 623-631. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"usc","label":"10 U.S.C. § 16132","url":"https://www.law.cornell.edu/uscode/text/10/16132","by":{"2":"20"}},{"t":"law","label":"Pub. L. No. 110-252","url":"https://www.govinfo.gov/link/plaw/110/public/252","by":{"2":"19"}},{"t":"law","label":"Pub. L. No. 111-377","url":"https://www.govinfo.gov/link/plaw/111/public/377","by":{"2":"21"}}]};